from pathlib import Path
import subprocess,json,hashlib,shutil
root=Path.cwd();s=root/'.local/step07-ci-prerequisites';out=root/'docs/evidence/step-07/ci-prerequisites';source=json.loads((s/'source-freeze.json').read_text())['sourceSHA'];assert subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()==source;out.mkdir(parents=True,exist_ok=False);sha=lambda b:hashlib.sha256(b).hexdigest();origins=[]
def capture(p,target,exact=False):
 raw=p.read_bytes();q=out/target;q.parent.mkdir(parents=True,exist_ok=True)
 if exact:shutil.copyfile(p,q)
 elif p.suffix in ['.log','.py','.mjs','.yml']:
  q.write_text(json.dumps({'privateOriginal':str(p.relative_to(root)),'originalSHA256':sha(raw),'originalBytes':len(raw),'text':raw.decode().replace(str(root),'<CODING_WORKTREE>'),'sanitized':True},indent=2)+'\n')
 else:q.write_text(raw.decode().replace(str(root),'<CODING_WORKTREE>'))
 origins.append({'privateOriginal':str(p.relative_to(root)),'originalSHA256':sha(raw),'originalBytes':len(raw),'evidenceCopy':str(q.relative_to(out)),'evidenceSHA256':sha(q.read_bytes()),'evidenceBytes':q.stat().st_size,'exact':exact})
for p in sorted(s.iterdir()):
 if not p.is_file() or p.name in ['source-before.json','prior-progress.json']:continue
 if p.suffix=='.json':capture(p,'results/'+p.name)
 elif p.suffix in ['.log','.py','.mjs','.yml']:capture(p,'raw/'+p.name+'.json')
manifest=next((s/'full-history-workspace').glob('artifacts/step07-'+source[:12]+'*/manifest.json'));capture(manifest,'engineering-manifest.json',exact=True)
old=root/'.local/step07-ci-history/services-after.log';capture(old,'old-service-probe-original.log.json')
oldRepro=root/'.local/step07-ci-history/shallow-reproduction.json';capture(oldRepro,'retained-shallow-reproduction.json')
r5=root/'docs/evidence/step-07/ci-history/results/parent-r5.json';capture(r5,'parent-r5.json',exact=True)
private=[{'path':str(p.relative_to(root)),'sha256':sha(p.read_bytes()),'bytes':p.stat().st_size} for p in sorted(s.iterdir()) if p.is_file()]
(out/'original-file-provenance.json').write_text(json.dumps({'sourceSHA':source,'files':origins,'privateFiles':private,'privateSnapshot':'Finalized top-level raw logs/probes fixed snapshot; later docs commit/progress audit separate; dependencies/browser binaries/DB/env/Git stores not copied'},indent=2)+'\n')
(out/'configuration.json').write_text(json.dumps({'role':'step_coder','model':'gpt-6.1-sol','reasoningEffort':'xhigh','serviceTier':'default(Standard)','sameCID':'01a132c0-f44b-75f0-bea5-7f4e5e77a6ea','serverFinalFields':'UNVERIFIED_NOT_EXPOSED','formalReviewsUsed':5,'nextRound':6,'mechanicalCap':None,'authorization':'2026-10-14 user removed mechanical cap, history not reset','collaborationUsed':False,'globalConfigChanged':False,'newIndependentReview':'NOT_EXECUTED_BY_CODER','candidateCI':'NOT_EXECUTED_BY_CODER','ApproveMergePushRelease':'NOT_EXECUTED','steps08_09_10':'NOT_STARTED'},indent=2)+'\n')
print('captured',len(origins),'raw originals, preserved both CI failures and service-probe correction')
